import { db, demoLearnerId } from "../../_lib/db.js";
import { allowMethod, enforceRateLimit, handleError, send } from "../../_lib/http.js";
export default async function handler(req,res){if(!allowMethod(req,res,"GET"))return;try{enforceRateLimit(req);const sql=db();const [skills,recommendations,trend]=await Promise.all([sql`SELECT skill_id,label,category,round(proficiency)::int AS proficiency,observation_count,trend FROM learner_skill_profiles WHERE learner_id=${demoLearnerId()} ORDER BY proficiency DESC`,sql`SELECT skill_id,scenario_id,caller_profile_id,rationale,priority FROM practice_recommendations WHERE learner_id=${demoLearnerId()} AND active=true ORDER BY priority`,sql`SELECT created_at,score,processing_score,interview_score FROM learning_attempts WHERE learner_id=${demoLearnerId()} AND score IS NOT NULL ORDER BY created_at`]);send(res,200,{learner_id:demoLearnerId(),skills,recommendations,trend,strengths:skills.filter(x=>x.proficiency>=80).slice(0,3),gaps:[...skills].sort((a,b)=>a.proficiency-b.proficiency).slice(0,3)});}catch(error){handleError(res,error);} }
